        AND COALESCE(ot.id_esquema, -1) = COALESCE(e.id_esquema, -1)
        AND COALESCE(ot.id_tabla, -1) = COALESCE(td.id_tabla, -1)
        AND COALESCE(ot.id_columna, -1) = COALESCE(NULL, -1)
