INSERT INTO cultura.idioma (id, nombre, familia_linguistica, estado_vitalidad, descripcion, carga_id) OVERRIDING SYSTEM VALUE VALUES
    (2, 'Q''eqchi''', 'Maya', 'Vital', 'Idioma maya con la mayor extensión territorial y rápido crecimiento, hablado principalmente en el norte y oriente.', 88),
    (3, 'Kaqchikel', 'Maya', 'Vital', 'Idioma maya del altiplano central, históricamente hablado por el reino Kaqchikel en Iximché.', 88),
    (4, 'Mam', 'Maya', 'Vital', 'Idioma maya de gran antigüedad hablado en el occidente del país, fronterizo con México.', 88),
    (23, 'Poqomchi''', 'Maya', 'Vital', 'Idioma maya hablado principalmente en Alta Verapaz, Baja Verapaz y El Quiché.', 88),
    (24, 'Tz''utujil', 'Maya', 'Vital', 'Idioma hablado en la cuenca del Lago de Atitlán en Sololá y Suchitepéquez.', 88),
    (25, 'Ch''orti''', 'Maya', 'En peligro', 'Idioma maya del oriente del país, estrechamente relacionado con el área arqueológica maya clásica.', 88),
    (26, 'Achi''', 'Maya', 'Vital', 'Idioma hablado en el departamento de Baja Verapaz, famoso por su obra de teatro del siglo XV Rabinal Achi''.', 88),
    (5, 'Garífuna', 'Arahuaca', 'En peligro', 'Idioma hablado por la comunidad de afrodescendientes garífunas en la costa atlántica (Izabal).', 88),
    (6, 'Xinka', 'Aislada', 'Crítico', 'Familia de lenguas no mayas del suroriente de Guatemala con muy pocos hablantes fluidos actualmente.', 88),
    (29, 'Akateko', 'Maya', 'Vital', 'Idioma maya hablado principalmente en el noroccidente del departamento de Huehuetenango.', 88),
    (30, 'Awakateko', 'Maya', 'Vital', 'Idioma maya hablado en el municipio de Aguacatán, Huehuetenango.', 88),
    (31, 'Chuj', 'Maya', 'Vital', 'Idioma maya del norte de Huehuetenango, emparentado con las lenguas de la rama q''anjob''al.', 88),
    (32, 'Ixil', 'Maya', 'Vital', 'Idioma hablado en la región norcentral de El Quiché (triángulo Ixil: Nebaj, Chajul y Cotzal).', 88),
    (33, 'Jakalteko (Popti'')', 'Maya', 'Vital', 'Idioma maya hablado en la región huista de Huehuetenango, fronteriza con Chiapas.', 88),
    (34, 'Q''anjob''al', 'Maya', 'Vital', 'Idioma maya hablado en el altiplano de Huehuetenango, reconocido por su rica tradición oral.', 88),
    (35, 'Sakapulteko', 'Maya', 'En peligro', 'Idioma maya minoritario hablado en el municipio de Sacapulas, El Quiché.', 88),
    (36, 'Sipakapense', 'Maya', 'En peligro', 'Idioma maya minoritario hablado en el municipio de Sipacapa, San Marcos.', 88),
    (37, 'Tektiteko', 'Maya', 'Crítico', 'Idioma maya minoritario hablado en el municipio de Tectitán, Huehuetenango.', 88),
    (38, 'Uspanteko', 'Maya', 'En peligro', 'Idioma maya hablado en el municipio de Uspantán, El Quiché.', 88),
    (39, 'Mopan', 'Maya', 'En peligro', 'Idioma maya hablado en el oriente de Petén, colindante con Belice.', 88),
    (40, 'Itza''', 'Maya', 'Crítico', 'Idioma maya histórico del Petén, hablado en las cercanías del Lago Petén Itzá.', 88),
    (41, 'Chalchiteko', 'Maya', 'Vital', 'Idioma maya reconocido en 2003, hablado principalmente en el municipio de Aguacatán, Huehuetenango.', 88),
    (42, 'Poqomam', 'Maya', 'Vital', 'Idioma maya hablado en pequeñas comunidades dispersas en Guatemala, Jalapa y Escuintla.', 88),
    (1, 'K''iche''', 'Maya', 'Vital', 'El idioma maya con mayor número de hablantes en Guatemala, hablado en el altiplano central y occidental.', 88);
