INSERT INTO cultura.evento_cultural (id, nombre, tipo_evento, mes_celebracion, dia_inicio, dia_fin, descripcion, recomendaciones_viaje, carga_id) OVERRIDING SYSTEM VALUE VALUES
    (1, 'Feria de Jocotenango', 'Feria Patronal', 8, 15, 15, 'Celebración en honor a la Virgen de la Asunción con juegos de feria, comida típica y procesiones.', 'Llegar temprano ya que se llena mucho. Utilizar parqueos oficiales autorizados.', 88),
    (2, 'Festival de Barriletes Gigantes de Sumpango', 'Festival Artístico', 11, 1, 1, 'Exhibición y vuelo de coloridos barriletes gigantes hechos de papel de china que comunican a los vivos con los muertos.', 'Llevar ropa cómoda, protector solar y gorra. El tráfico de ingreso es pesado ese día.', 88),
    (3, 'Feria Patronal de Cobán', 'Feria Patronal', 8, 1, 6, 'Celebración en honor a Santo Domingo de Guzmán, con danzas folklóricas y ceremonias religiosas.', 'Excelente oportunidad para probar el Kaq''ik local auténtico.', 88),
    (4, 'Festival Folklórico Nacional Rabin Ajaw', 'Festival Artístico', 7, 25, 27, 'Elección y coronación de la reina indígena nacional Rabin Ajaw, un evento cultural y ceremonial maya de gran importancia.', 'Reservar hotel con mucha anticipación ya que atrae a visitantes de todo el país.', 88),
    (58, 'Fiesta de Santo Tomás', 'Feria Patronal', 12, 13, 21, 'Celebración patronal en honor a Santo Tomás Apóstol, conocida por sus coloridas danzas folklóricas (incluyendo el Palo Volador) y ceremonias sincréticas mayas.', 'Reservar hospedaje con mucha anticipación. Llevar ropa muy abrigada ya que el clima es frío en diciembre.', 88),
    (59, 'Semana Santa en Antigua Guatemala', 'Celebración Religiosa', 3, 22, 29, 'Conmemoración de la Pasión, Muerte y Resurrección de Jesús con solemnes procesiones y alfombras de aserrín de colores que cubren las calles empedradas.', 'Llegar a pie o en transporte colectivo, dado que el tránsito de vehículos se restringe en el casco colonial.', 88),
    (60, 'Carrera de Cintas de Todos Santos Cuchumatán', 'Celebración Tradicional', 11, 1, 1, 'Tradicional carrera de caballos donde los jinetes visten el traje típico local de rayas rojas y blancas, celebrada como ritual el Día de Todos los Santos.', 'Respetar las costumbres locales y mantener una distancia prudente de la pista de carreras por seguridad.', 88),
    (61, 'Quema del Diablo', 'Celebración Tradicional', 12, 7, 7, 'Tradición popular donde se quema una figura del diablo o piñata de color rojo a las 18:00 horas, simbolizando la purificación espiritual para recibir la Navidad.', 'Mantener la precaución con el fuego y los juegos pirotécnicos en las calles.', 88),
    (62, 'Feria Patronal de Palín (Virgen de Concepción)', 'Feria Patronal', 12, 6, 9, 'Feria patronal emblemática por el Baile de la Conquista y venta de variada comida tradicional poqomam.', 'Degustar los platillos y atoles locales en las inmediaciones de la ceiba central.', 88),
    (63, 'Feria Patronal de Sololá (Virgen de Concepción)', 'Feria Patronal', 12, 8, 8, 'Celebración de la patrona de Sololá con procesiones que combinan la fe católica y ceremonias mayas tradicionales, además de danzas de Moros y Cristianos.', 'Aprovechar para visitar el mercado local y disfrutar del paisaje hacia el Lago de Atitlán.', 88),
    (64, 'Feria Patronal de Cantel', 'Feria Patronal', 8, 12, 18, 'Celebración en honor a la Virgen de la Asunción con actividades culturales, deportivas, desfiles y venta de comida típica del altiplano.', 'Llevar ropa abrigada y paraguas ya que agosto es mes de lluvia en el altiplano occidental.', 88),
    (103, 'Fiestas Julias de Huehuetenango', 'Feria Patronal', 7, 10, 16, 'Celebración patronal en honor a la Virgen del Carmen con ferias comerciales, actividades culturales y desfiles de carrozas.', 'Disfrutar de las exposiciones de café y artesanías locales de Huehuetenango.', 88),
    (180, 'Feria Titular de Sansare', 'Feria Patronal', 8, 8, 11, 'Feria titular y celebración anual del municipio de Sansare, departamento de El Progreso. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (191, 'Feria Titular de Ciudad Vieja', 'Feria Patronal', 1, 13, 16, 'Feria titular y celebración anual del municipio de Ciudad Vieja, departamento de Sacatepéquez. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (192, 'Feria Patronal de San Miguel Dueñas (En honor a San Miguel Arcángel)', 'Feria Patronal', 9, 26, 29, 'Feria patronal del municipio de San Miguel Dueñas, celebrada en honor a su santo patrono San Miguel Arcángel. Se caracteriza por coloridas procesiones, desfiles hípicos, danzas folclóricas y venta de platos típicos de Sacatepéquez.', 'Ideal para presenciar las tradiciones religiosas del municipio. Disfrutar de los bailes de moros y cristianos en el atrio parroquial.', 88),
    (193, 'Feria Titular de Alotenango', 'Feria Patronal', 11, 11, 14, 'Feria titular y celebración anual del municipio de Alotenango, departamento de Sacatepéquez. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (194, 'Feria Patronal de San Antonio Aguas Calientes (En honor a San Antonio de Padua)', 'Feria Patronal', 6, 10, 13, 'Feria patronal del municipio de San Antonio Aguas Calientes, celebrada en honor a su santo patrono San Antonio de Padua. Se caracteriza por coloridas procesiones, desfiles hípicos, danzas folclóricas y venta de platos típicos de Sacatepéquez.', 'Ideal para presenciar las tradiciones religiosas del municipio. Disfrutar de los bailes de moros y cristianos en el atrio parroquial.', 88),
    (195, 'Feria Patronal de Santa Catarina Barahona (En honor a Santa Catarina de Alejandría)', 'Feria Patronal', 11, 22, 25, 'Feria patronal del municipio de Santa Catarina Barahona, celebrada en honor a su santo patrono Santa Catarina de Alejandría. Se caracteriza por coloridas procesiones, desfiles hípicos, danzas folclóricas y venta de platos típicos de Sacatepéquez.', 'Ideal para presenciar las tradiciones religiosas del municipio. Disfrutar de los bailes de moros y cristianos en el atrio parroquial.', 88),
    (196, 'Feria Titular de Chimaltenango', 'Feria Patronal', 2, 14, 17, 'Feria titular y celebración anual del municipio de Chimaltenango, departamento de Chimaltenango. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (198, 'Feria Patronal de San Martín Jilotepeque (En honor a San Martín de Tours)', 'Feria Patronal', 11, 8, 11, 'Feria patronal del municipio de San Martín Jilotepeque, celebrada en honor a su santo patrono San Martín de Tours. Se caracteriza por coloridas procesiones, desfiles hípicos, danzas folclóricas y venta de platos típicos de Chimaltenango.', 'Ideal para presenciar las tradiciones religiosas del municipio. Disfrutar de los bailes de moros y cristianos en el atrio parroquial.', 88),
    (199, 'Feria Titular de Comalapa', 'Feria Patronal', 9, 9, 12, 'Feria titular y celebración anual del municipio de Comalapa, departamento de Chimaltenango. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (201, 'Feria Titular de Pochuta', 'Feria Patronal', 8, 8, 11, 'Feria titular y celebración anual del municipio de Pochuta, departamento de Chimaltenango. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
    (202, 'Feria Titular de Patzicía', 'Feria Patronal', 9, 9, 12, 'Feria titular y celebración anual del municipio de Patzicía, departamento de Chimaltenango. Se organizan eventos culturales, deportivos, coronación de reinas locales y la tradicional quema de fuegos artificiales.', 'Visitar el parque municipal y degustar las comidas tradicionales de la feria como elotes locos, tostadas y atol local.', 88),
