INSERT INTO transporte.tipo_transporte (id_tipo_transporte, codigo, nombre, descripcion, carga_id) OVERRIDING SYSTEM VALUE VALUES
    (1, 'TUC_TUC', 'Tuc-tuc', 'Mototaxi local para traslados cortos de pasajeros dentro del municipio.', 95),
    (2, 'EXTRAURBANO', 'Autobús extraurbano', 'Autobús de parrilla tradicional (chicken bus) para rutas intermunicipales.', 95),
    (3, 'LANCHA', 'Lancha colectiva', 'Transporte acuático en lanchas compartidas para destinos alrededor de lagos (ej. Atitlán).', 95),
    (4, 'FLETERO', 'Microbús / Fletero', 'Microbús rápido para trayectos rotativos intercomunitarios.', 95),
    (5, 'SHUTTLE', 'Shuttle turístico', 'Transporte privado o compartido con aire acondicionado ideal para turistas.', 95),
    (6, 'TAXI', 'Taxi local', 'Servicio de transporte privado individual en vehículo sedán.', 95);
INSERT INTO transporte.tipo_via (id_tipo_via, codigo, nombre, descripcion, carga_id) OVERRIDING SYSTEM VALUE VALUES
    (1, 'INTERAMERICANA', 'Carretera Interamericana (CA-1)', 'Carretera principal asfaltada de alta velocidad de 2 o 4 carriles.', 95),
    (2, 'NACIONAL_ASFALTO', 'Ruta Nacional Asfaltada', 'Vías de conexión asfaltadas de dos carriles.', 95),
    (3, 'TERRACERIA', 'Camino de terracería', 'Vías de tierra y balastro. Sujetas a afectaciones climáticas.', 95),
    (4, 'ACUATICA', 'Vía Fluvial / Lacustre', 'Rutas de navegación acuática en lancha o transbordador.', 95),
    (5, 'PEATONAL', 'Sendero Peatonal', 'Caminos rurales transitables únicamente a pie o a caballo.', 95);
